// Singleton: one shared connection per process
let instance = null;
export function getDb() {
  if (!instance) instance = connect(process.env.DB_URL);
  return instance;
}

// Factory: creation logic in one place
const notifiers = {
  email: (msg) => sendEmail(msg),
  sms: (msg) => sendSms(msg),
};
export function notify(channel, msg) {
  const send = notifiers[channel];
  if (!send) throw new Error("Unknown channel: " + channel);
  return send(msg);
}

class JobQuery {
  constructor() {
    this.filters = {};
    this.sort = {};
    this.limit = 20;
  }
  where(cond) { Object.assign(this.filters, cond); return this; }
  orderBy(field, dir = 1) { this.sort[field] = dir; return this; }
  take(n) { this.limit = n; return this; }
  build() {
    return { filter: this.filters, sort: this.sort, limit: this.limit };
  }
}

const query = new JobQuery()
  .where({ remote: true })
  .orderBy("postedAt", -1)
  .take(10)
  .build();   // { filter: { remote: true }, sort: { postedAt: -1 }, limit: 10 }

// Legacy service speaks XML; the rest of the app wants objects
class LegacyBilling {
  getInvoiceXml(id) {
    return `<invoice id="${id}" total="42.00"/>`;
  }
}

// Adapter presents the interface the app expects
class BillingAdapter {
  constructor(legacy) { this.legacy = legacy; }
  getInvoice(id) {
    const xml = this.legacy.getInvoiceXml(id);
    const total = Number(/total="([\d.]+)"/.exec(xml)?.[1] ?? 0);
    return { id, total, currency: "USD" };
  }
}

const billing = new BillingAdapter(new LegacyBilling());
